-- Parts picking: review current pending requests, then issue a bounded selection atomically.
begin;
do $$begin if public.get_full_imei_save_fix_version()is distinct from '20261029-full-imei-save-fix-1'then raise exception 'Verified IMEI save fix is required.';end if;end;$$;
create or replace function public.prepare_parts_picking_v1(p_groups jsonb)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');perform greenloop_private.pf_cap('parts','technician_report');perform greenloop_private.pf_cap('parts','issue');
 if jsonb_typeof(p_groups)is distinct from 'array'or jsonb_array_length(p_groups)not between 1 and 50 or exists(select 1 from jsonb_array_elements(p_groups)g where jsonb_typeof(g)<>'object'or not(g?'technician_key'and g?'model'and g?'color'and g?'part_name')or(select count(*)from jsonb_object_keys(g))<>4 or exists(select 1 from jsonb_each(g)e where jsonb_typeof(e.value)<>'string'or length(e.value#>>'{}')>200))then raise exception 'Select up to 50 valid report lines.'using errcode='22023';end if;
 with selected as materialized(select s.*from greenloop_private.technician_parts_pending()s where exists(select 1 from jsonb_array_elements(p_groups)g where s.technician_key=g->>'technician_key'and s.model=g->>'model'and s.color=g->>'color'and s.part_name=g->>'part_name'))
 select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('revision',o.revision,'stocks',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'name',i.part_name||' / '||i.sku,'quantity',i.stock_quantity)order by i.sku)from public.part_inventory i where i.is_active and i.stock_quantity>0 and greenloop_private.pp_key(i.part_name)=greenloop_private.pp_key(s.part_name)),'[]'))order by s.part_name,s.model,s.color,s.technician_name,s.ordered_at,s.imei,s.request_id),'[]'),'phones',count(distinct s.device_id),'quantity',coalesce(sum(s.quantity),0))into result from selected s join greenloop_private.parts_flow_orders o on o.id=s.order_id;
 if jsonb_array_length(result->'rows')>200 then raise exception 'Select fewer report lines; each bulk issue supports up to 200 requests.'using errcode='22023';end if;return result;
end;$$;
create or replace function public.issue_parts_picking_v1(p_lines jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare line_item jsonb;o greenloop_private.parts_flow_orders%rowtype;issued jsonb;results jsonb:='[]';total integer:=0;begin
 perform greenloop_private.pf_cap('parts','view');perform greenloop_private.pf_cap('parts','technician_report');perform greenloop_private.pf_cap('parts','issue');
 if jsonb_typeof(p_lines)is distinct from 'array'or jsonb_array_length(p_lines)not between 1 and 200 then raise exception 'Select 1 to 200 pending part requests.'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_lines)x where jsonb_typeof(x)<>'object'or not(x?'order_id'and x?'request_id'and x?'revision'and x?'quantity')or exists(select 1 from jsonb_object_keys(x)k where k not in('order_id','request_id','revision','quantity','unit_price','stock_id','technician_key','model','color','part_name'))or coalesce(x->>'quantity','')!~'^[0-9]+$'or(x->>'quantity')::integer not between 1 and 10000 or coalesce(x->>'revision','')!~'^[0-9]+$')then raise exception 'Use valid whole quantities and current report revisions.'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_lines)x group by x->>'request_id'having count(*)>1)or exists(select 1 from jsonb_array_elements(p_lines)x group by x->>'order_id'having count(distinct x->>'revision')<>1)then raise exception 'Each request must appear once with one current revision per phone.'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_lines)x where not(x?'technician_key'and x?'model'and x?'color'and x?'part_name')or exists(select 1 from jsonb_each(x)e where e.key in('technician_key','model','color','part_name')and(jsonb_typeof(e.value)<>'string'or length(e.value#>>'{}')>200)))then raise exception 'Review the current technician and part details first.'using errcode='22023';end if;
 perform pg_advisory_xact_lock(19920261026);
 for line_item in select jsonb_build_object('id',value->>'order_id','revision',min((value->>'revision')::integer))from jsonb_array_elements(p_lines)group by value->>'order_id'order by value->>'order_id'loop
  o:=greenloop_private.pf_lock((line_item->>'id')::uuid,(line_item->>'revision')::integer);
 end loop;
 if(with current_rows as materialized(select *from greenloop_private.technician_parts_pending())select exists(select 1 from jsonb_array_elements(p_lines)x where not exists(select 1 from current_rows r where r.request_id=(x->>'request_id')::uuid and r.order_id=(x->>'order_id')::uuid and r.technician_key=x->>'technician_key'and r.model=x->>'model'and r.color=x->>'color'and r.part_name=x->>'part_name')))then raise exception 'The selected phone assignment or parts changed. Review the current report again.'using errcode='40001';end if;
 -- The existing issuer validates cycle, pending balance, return reviews, inventory and prices.
 -- Any failed line aborts this transaction, including earlier issues in the batch.
 for line_item in select value from jsonb_array_elements(p_lines)order by value->>'order_id',value->>'request_id'loop
  select *into o from greenloop_private.parts_flow_orders where id=(line_item->>'order_id')::uuid;
  issued:=public.issue_parts_flow_v1(o.id,o.revision,(line_item->>'request_id')::uuid,(line_item->>'quantity')::integer,nullif(line_item->>'unit_price','')::numeric,nullif(line_item->>'stock_id','')::uuid);
  results:=results||jsonb_build_array(jsonb_build_object('request_id',line_item->>'request_id','issue_id',issued->>'issue_id','quantity',(line_item->>'quantity')::integer));total:=total+(line_item->>'quantity')::integer;
 end loop;
 return jsonb_build_object('issued',true,'requests',jsonb_array_length(results),'quantity',total,'results',results);
end;$$;
insert into greenloop_private.capability_rpc_rules values('prepare_parts_picking_v1','{"page":"parts","capability":"issue","read":true}'),('issue_parts_picking_v1','{"page":"parts","capability":"issue"}')on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in('prepare_parts_picking_v1','issue_parts_picking_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select string_agg('$'||i,','order by i)into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;
end;$wrap$;
create table if not exists greenloop_private.parts_picking_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_picking_installation enable row level security;revoke all on greenloop_private.parts_picking_installation from public,anon,authenticated;
create or replace function public.get_parts_picking_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_full_imei_save_fix_version()='20261029-full-imei-save-fix-1'and(select count(*)=5 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.parts_picking_installation)and exists(select 1 from pg_class where oid='greenloop_private.parts_picking_installation'::regclass and relrowsecurity)and not has_table_privilege('anon','greenloop_private.parts_picking_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_table_privilege('authenticated','greenloop_private.parts_picking_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')then '20261029-parts-picking-1'end;$$;
revoke all on function public.get_parts_picking_version()from public;grant execute on function public.get_parts_picking_version()to anon,authenticated;
insert into greenloop_private.parts_picking_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where p.oid='public.get_parts_picking_version()'::regprocedure or(p.pronamespace='public'::regnamespace and p.proname in('prepare_parts_picking_v1','issue_parts_picking_v1'))or p.oid in(select to_regprocedure(implementation)from greenloop_private.office_routines where to_regprocedure(identity)in('public.prepare_parts_picking_v1(jsonb)'::regprocedure,'public.issue_parts_picking_v1(jsonb)'::regprocedure))on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_parts_picking_version()is distinct from '20261029-parts-picking-1'then raise exception 'Parts picking verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_parts_picking_version()as installed_parts_picking_version;
